import bcrypt from 'bcryptjs';import jwt from 'jsonwebtoken';import User from '../models/User.js';import Member from '../models/Member.js';
const safe=u=>({id:u._id,username:u.username,email:u.email,name:u.name,role:u.role,memberId:u.member?.memberId||null});
export async function register(req,res){const name=String(req.body.name||'').trim(),email=String(req.body.email||'').trim().toLowerCase(),username=String(req.body.username||email.split('@')[0]).trim().toLowerCase(),password=String(req.body.password||'');if(!name||!email||!/^\S+@\S+\.\S+$/.test(email)||password.length<8)return res.status(400).json({message:'Name, valid email and password (at least 8 characters) are required'});if(await User.exists({$or:[{email},{username}]}))return res.status(409).json({message:'An account with this email or username already exists'});const user=await User.create({name,email,username,password:await bcrypt.hash(password,12),role:'member'});try{const member=await Member.create({memberId:`LIB-${Date.now().toString().slice(-8)}`,accountUser:user._id,name,email,status:'active'});user.member=member._id;await user.save();}catch(e){await User.findByIdAndDelete(user._id);throw e;}const token=jwt.sign({id:user._id.toString(),username:user.username,name:user.name,role:user.role,memberId:user.member.toString()},process.env.JWT_SECRET,{expiresIn:'12h'});res.status(201).json({token,user:safe(await user.populate('member','memberId'))});}
export async function login(req,res){const identity=String(req.body.username||req.body.email||'').trim().toLowerCase(),password=String(req.body.password||'');if(!identity||!password)return res.status(400).json({message:'Username/email and password are required'});const user=await User.findOne({$or:[{username:identity},{email:identity}]}).populate('member','memberId');if(!user||!(await bcrypt.compare(password,user.password)))return res.status(401).json({message:'Invalid username/email or password'});const token=jwt.sign({id:user._id.toString(),username:user.username,name:user.name,role:user.role,memberId:user.member?._id?.toString()||null},process.env.JWT_SECRET,{expiresIn:'12h'});res.json({token,user:safe(user)});}
export async function me(req,res){const user=await User.findById(req.user.id).populate('member','memberId');if(!user)return res.status(404).json({message:'User not found'});res.json(safe(user));}
